  js("[...document.querySelectorAll('#primary-content [data-action=claim]')].find(n=>JSON.parse(n.dataset.args).id==='prepare').click()")
  ck('Existing approved preparation quest uses its own reward ledger',"AL.game.quests.prepare&&AL.game.level>=2")
  store('rocks');details('rock:fiji:0');js("window.rockMoney=AL.game.credits;document.querySelector('[data-form=storePurchase]').requestSubmit()")
  ck('Rock purchase waits for actual placement and does not charge early',"AL.UI.placing&&!AL.Tutorial.state(AL.game).completed.hardscape&&AL.game.credits===rockMoney")
  c.call('Input.dispatchKeyEvent',{'type':'keyDown','key':'Escape','code':'Escape'})
  ck('Canceled placement does not complete shelter or spend money',"!AL.UI.placing&&!AL.Tutorial.tank(AL.game).hardscape.length&&AL.game.credits===rockMoney")
  store('rocks');details('rock:fiji:0');js("document.querySelector('[data-form=storePurchase]').requestSubmit();document.getElementById('aquarium').focus()")
  c.call('Input.dispatchKeyEvent',{'type':'keyDown','key':'Enter','code':'Enter'})
  ck('Real keyboard placement creates one rock and verifies shelter',"AL.Tutorial.tank(AL.game).hardscape.length===1&&!!AL.Tutorial.state(AL.game).completed.hardscape&&AL.game.credits<rockMoney")
  js("AL.UI.close();AL.Shell.close();AL.Shell.open('equipment','care');AL.InventoryUI.inspect({type:'heater'})")
  ck('Thermostat stays in installed equipment inspector, not a standalone panel',"document.querySelector('[data-form=equipmentThermostat]')&&!document.querySelector('#primary-content form[data-form=controls]')")
  js("const f=document.querySelector('[data-form=equipmentThermostat]');f.elements.temperature.value='25';window.beforeThermostat=AL.Tutorial.tank(AL.game).waterParams.temperature;f.requestSubmit()")
  ck('Saving thermostat does not force measured water to25C',"AL.Tutorial.tank(AL.game).equipment.find(e=>e.type==='heater').temperatureTarget===25&&Math.abs(AL.Tutorial.tank(AL.game).waterParams.temperature-beforeThermostat)<.05&&AL.Tutorial.tank(AL.game).waterParams.temperature<24")
  js("AL.UI.close();AL.Shell.close();AL.game.settings.speed=0;window.warmSteps=0;for(;warmSteps<3000&&AL.Tutorial.tank(AL.game).waterParams.temperature<24;warmSteps++)AL.Sim.step(AL.game,5);AL.UI.render()")
