  js("window.cycleStart=AL.game.time;window.cycleSteps=0;window.auditBefore=AL.Tutorial.state(AL.game).nextAudit;for(;cycleSteps<1000&&!AL.Preparation.state(AL.Tutorial.tank(AL.game)).cycled;cycleSteps++)AL.Sim.step(AL.game,5);AL.UI.render()")
  ck('Cycle completes only through432 authoritative five-minute steps',"cycleSteps>=431&&cycleSteps<=433&&AL.game.time-cycleStart>=2155&&AL.Preparation.state(AL.Tutorial.tank(AL.game)).cycled&&!!AL.Tutorial.state(AL.game).completed.cycle")
  ck('Simulation does not spam a debug event every fixed step',"AL.Tutorial.state(AL.game).nextAudit-auditBefore<20")
