  ck('Actual new aquarium purchase creates an empty unprepared alternate receiver',"AL.game.tanks.length===2&&AL.game.tanks.find(t=>t.id===unreadyReceiver).emptyDry&&!AL.game.tanks.find(t=>t.id===unreadyReceiver).prepared&&AL.Tutorial.state(AL.game).tankId===originalGuideTank")
  store('fish')
  wait("!!AL.Tutorial.state(AL.game).completed.shop")
  js("window.rotationDays=0;while(!AL.Tutorial.candidate(AL.game)&&rotationDays++<30){for(let i=0;i<288;i++)AL.Sim.step(AL.game,5);}AL.Store.render();window.starter=AL.Tutorial.candidate(AL.game);if(!starter)throw Error('No safe beginner listing in legitimate30-day rotation fixture')")
  ck('Recommendation fits actual tank, supported care, level, stock and price',"starter.kind==='fish'&&starter.stock>0&&starter.price<=AL.game.credits&&AL.Tutorial.report(AL.game,AL.Tutorial.tank(AL.game),starter.species).ok&&AL.Data.species[starter.species].level<=AL.game.level")
  details(c.evaluate('starter.id'));wait("!!AL.Tutorial.state(AL.game).completed.details")
  ck('Actual listing details retain price, species care and receiving destination',"!!document.getElementById('purchase-destination')&&document.getElementById('dialog-body').textContent.includes(AL.Data.species[starter.species].scientificName)")
  ck('Every owned aquarium is listed during receiving selection',"document.querySelectorAll('#purchase-destination option').length===AL.game.tanks.length")
